                            'barcode'=> '8902061041805',
                            'is_primary'=> true
                        ]
                    ]
                ]
            ]
        ],
        [
            'name'=> 'MILTON HOT 24 COLD',
            'product_code'=> 'PRD-698AD93A6CF90',
            'description'=> null,
            'category_id'=> 1,
            'brand_id'=> 1,
            'tax_category_id'=> 4,
            'is_active'=> true,
            'is_returnable'=> true,
            'variants'=> [
                [
                    'variant_name'=> 'Standard',
                    'sku'=> 'MILTONHO-STANDA-A6CF',
                    'unit_id'=> 1,
                    'net_quantity'=> 1,
                    'mrp'=> 1140,
                    'selling_price'=> 950,
                    'cost_price'=> 750,
                    'min_selling_price'=> 850,
                    'status'=> true,
                    'barcodes'=> [
                        [
                            'barcode'=> '8902061213097',
                            'is_primary'=> true
                        ]
                    ]
                ]
            ]
        ]
    ],
        ];

        DB::transaction(function () use ($data) {

            foreach ($data['products'] as $productData) {

                $product = Product::create([
                    'name'            => $productData['name'],
                    'product_code'    => $this->generateUniqueProductCode(),
                    'description'     => $productData['description'],
                    'category_id'     => $productData['category_id'],
                    'brand_id'        => $productData['brand_id'],
                    'tax_category_id' => $productData['tax_category_id'],
                    'is_active'       => $productData['is_active'],
                    'is_returnable'   => $productData['is_returnable'],
                ]);

                foreach ($productData['variants'] as $variantData) {

                    $variant = ProductVariant::create([
                        'product_id'        => $product->id,
                        'variant_name'      => $variantData['variant_name'],
                        'sku'               => $this->generateUniqueProductSku($variantData['sku']),
                        'unit_id'           => $variantData['unit_id'],
                        'net_quantity'      => $variantData['net_quantity'],
                        'mrp'               => $variantData['mrp'],
                        'selling_price'     => $variantData['selling_price'],
                        'cost_price'        => $variantData['cost_price'] ?? 0,
                        'min_selling_price' => $variantData['min_selling_price'] ?? null,
                        'status'            => $variantData['status'] ?? true,
                    ]);

                    foreach ($variantData['barcodes'] ?? [] as $barcodeData) {
                        Barcode::create([
                            'product_variant_id' => $variant->id,
                            'barcode'            => $this->generateUniqueProductbar($barcodeData['barcode']),
                            'is_primary'         => $barcodeData['is_primary'] ?? true,
                        ]);
                    }
                }
            }
        });

        return response()->json([
            'message' => 'Products imported successfully',
        ]);
    }

    private function generateUniqueProductCode(): string
    {
        do {
            $code = 'PRD-' . strtoupper(uniqid());
        } while (Product::where('product_code', $code)->exists());

        return $code;
    }
    private function generateUniqueProductSku(string $baseSku): string
    {
        if (!ProductVariant::where('sku', $baseSku)->exists()) {
            return $baseSku;
        }

        do {
            $code = $baseSku . '-' . random_int(0, 9) . chr(random_int(65, 90));
        } while (ProductVariant::where('sku', $code)->exists());

        return $code;
    }
    private function generateUniqueProductbar(string $bar): string
    {
        if (!Barcode::where('barcode', $bar)->exists()) {
            return $bar;
        }

        do {
            $code = $bar . random_int(0, 9) ;
        } while (Barcode::where('barcode', $code)->exists());

        return $code;
    }
}
